# GENERATED by Nekkora Studio ("Desenvolver automação") from the validated model and the ready PDD.
# Do not edit: fixes go to the model or the PDD, then the code is generated again (hand-edited files are kept).
"""Runs the process over a list.

Usage: python main.py --input <list.csv|list.xlsx> --spreadsheet <output.xlsx> --output <folder>
    [--channel chrome|chromium] [--headless] [--console]

The list has one column per input: termo_de_busca, endereco_do_artigo.
The spreadsheet is written only if ALL items succeed.
The previous option names (--entrada, --planilha, --saida) are still accepted.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from nekkora_rpa import Engine, EnvSecretProvider, load_config
from nekkora_rpa.errors import NekkoraRpaError
from nekkora_rpa.tabular import Column, TabularInputProvider, TabularSchema, read_tabular
from nekkora_rpa.xlsx import ColumnKind, OutputColumn, OverwritePolicy, XlsxResultSink, XlsxSchema

from automation.process import INPUT_COLUMNS, WikipediaBiographiesProcess

HERE = Path(__file__).resolve().parent
EXIT_CODES = {"COMPLETED": 0, "COMPLETED_WITH_FAILURES": 1, "STOPPED": 2, "INIT_FAILED": 3, "CANCELLED": 4}
INPUT_LIST = TabularSchema(tuple(Column(name) for name in INPUT_COLUMNS), reject_extra_columns=True)
SPREADSHEET = XlsxSchema(
    (
        OutputColumn("URL", "url", ColumnKind.URL),
        OutputColumn("Nome completo", "full_name", ColumnKind.TEXT),
        OutputColumn("Nascimento", "birth_date", ColumnKind.ISO_DATE),
        OutputColumn("Morte", "death_date", ColumnKind.ISO_DATE, required=False),
        OutputColumn("Nacionalidade", "nationality", ColumnKind.TEXT),
        OutputColumn("Ocupação", "occupation", ColumnKind.TEXT),
    ),
    key_field="url",
    sheet="Dados",
)
"""Output spreadsheet: the column headers are the contract of the spreadsheet; the fields are the row keys."""


def main(argv: list[str] | None = None) -> int:
    """Reads the arguments, runs the process and prints the summary (no values); returns the exit code."""
    parser = argparse.ArgumentParser(description="Generated process: biografias_da_wikipedia")
    parser.add_argument(
        "--input",
        "--entrada",
        dest="input",
        required=True,
        type=Path,
        help="CSV or XLSX list (one row per item)",
    )
    parser.add_argument(
        "--spreadsheet", "--planilha", dest="spreadsheet", required=True, type=Path, help="output .xlsx spreadsheet"
    )
    parser.add_argument(
        "--output",
        "--saida",
        dest="output",
        required=True,
        type=Path,
        help="run folder (events, checkpoint)",
    )
    parser.add_argument("--channel", choices=["chromium", "chrome"])
    parser.add_argument("--headless", action="store_true")
    parser.add_argument("--console", action="store_true")
    args = parser.parse_args(argv)
    run_folder = args.output.resolve()
    run_folder.mkdir(parents=True, exist_ok=True)
    overrides: dict[str, object] = {}
    if args.channel:
        overrides["browser.channel"] = args.channel
    if args.headless:
        overrides["browser.headless"] = True
    config = load_config(HERE / "config" / "execution.toml", overrides)
    try:
        input_list = read_tabular(args.input, INPUT_LIST)
        sink = XlsxResultSink(
            args.spreadsheet.resolve(),
            SPREADSHEET,
            state_dir=run_folder / "execucao",
            overwrite=OverwritePolicy.REPLACE,
            expected_rows=len(input_list.rows),
        )
    except NekkoraRpaError as error:
        print(json.dumps({"status": "INPUT_INVALID", "code": error.code.value, "detail": error.detail}))
        return 5
    process = WikipediaBiographiesProcess()
    engine = Engine(
        process,
        TabularInputProvider(input_list),
        sink,
        config,
        secrets=EnvSecretProvider(process.required_secrets),
        run_dir=run_folder / "execucao",
        console=args.console,
    )
    summary = engine.run()
    fields = summary.to_dict()
    published = ("execution_id", "status", "stop_code", "stop_detail", "counts", "output")
    print(json.dumps({key: fields[key] for key in published}))
    return EXIT_CODES[summary.status.value]


if __name__ == "__main__":
    sys.exit(main())
